    error('SPM dir not found: %s', spm_dir);
end
if ~exist(tpm_file, 'file')
    error('SPM TPM file not found: %s', tpm_file);
end

addpath(spm_dir);
spm('defaults', 'FMRI');
spm_jobman('initcfg');

